import * as THREE from './three.module.js';
import {STEP,RULES,PROFILES,BallSimulation,Ledger,makeIntent,makeRelease,batBasis,v,length} from './physics.js';
import {BatController} from './input.js';
const $=id=>document.getElementById(id);
export function boot({scene,camera,renderer,canvas,ball,batRig,bowler}){
  const control=new BatController();let ledger=new Ledger(),state='ready',paused=false,accumulator=0,last=performance.now(),phaseTime=0,sim=null,intent=null,deliveryId=0,sessionSeed=19470910,pose=control.step(STEP),replayTime=0,replaySpeed=.5,trajectory=null,soundOn=false,audio,lastEvent=0,activeModal=null,wasPaused=false,lastInput='',resetAfterClose=false;
  function configure(){control.mode=$('inputMode').value;control.sensitivity=Number($('sensitivity').value);control.invert=$('invert').checked;control.hand=$('hand').value;$('sensitivityValue').textContent=control.sensitivity.toFixed(1)+'×';$('inputLabel').textContent=control.mode==='trackpad'?'TWO-FINGER TRACKPAD':control.mode==='touch'?'TOUCH SWIPE':'MOUSE MOTION';$('hint').textContent=control.mode==='trackpad'?'TWO FINGERS: PULL BACK, THEN SWIPE FORWARD':'MOVE TO POSITION · STROKE FORWARD TO SWING';}
  for(const id of ['inputMode','sensitivity','invert','hand','surface'])$(id).addEventListener('input',configure);configure();
  control.onActivity=text=>{$('activity').textContent=text;};
  function audioHit(freq,duration,volume=.07){if(!soundOn)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,freq*.3),audio.currentTime+duration);g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
  function score(){ $('score').innerHTML=`${ledger.contacts}<span>/${ledger.deliveries}</span>`;$('over').textContent=`${Math.floor(ledger.legalBalls/6)}.${ledger.legalBalls%6}`;$('chase').textContent=`${ledger.wickets} bowled · ${ledger.boundaryRuns} boundary runs · ${ledger.deliveries} deliveries`;$('contactRate').textContent=ledger.deliveries?Math.round(ledger.contacts/ledger.deliveries*100)+'%':'—';const recent=ledger.events.slice(-6);$('deliveries').innerHTML='<span>CONTACTS / BALLS</span>'+Array.from({length:6},(_,i)=>`<i class="${recent[i]?'filled':''}">${recent[i]?recent[i].contacts-(ledger.events[ledger.events.indexOf(recent[i])-1]?.contacts||0)?'●':'·':'—'}</i>`).join('');}
  function removeTrail(){if(trajectory){scene.remove(trajectory);trajectory.geometry.dispose();trajectory.material.dispose();trajectory=null;}}
  function startDelivery(){if(activeModal)return;removeTrail();paused=false;$('pause').textContent='Ⅱ';state='runup';phaseTime=0;accumulator=0;sim=null;lastEvent=0;lastInput='';control.reset();control.active=true;pose=control.step(STEP);intent=makeIntent((sessionSeed+deliveryId*7919)>>>0);deliveryId++;$('panel').classList.add('hidden');$('analysis').classList.add('hidden');$('replayBar').classList.add('hidden');$('feedback').innerHTML='';$('activity').textContent='READ THE ACTION';}
  function animateBowler(time){if(!intent)return;const p=Math.min(1,time/intent.runupSeconds),g=bowler.g;g.position.set(.32,0,THREE.MathUtils.lerp(intent.spin?-22.5:-27.5,-18.3,p));g.rotation.set(0,0,0);const cycle=Math.sin(time*(intent.spin?8:13));bowler.limbs[0].rotation.x=cycle*.5;bowler.limbs[1].rotation.x=-cycle*.5;bowler.limbs[2].rotation.set(-cycle*.65,0,0);bowler.limbs[3].rotation.set(cycle*.65,0,0);if(p>.7){const a=(p-.7)/.3;bowler.limbs[3].rotation.x=-Math.PI*a;bowler.limbs[3].rotation.z=intent.armSlot*a;bowler.hand.rotation.y=intent.wrist*a;bowler.limbs[2].rotation.x=-Math.PI*.7*(1-a);g.rotation.z=Math.sin(a*Math.PI)*.09;bowler.limbs[0].rotation.x=-.3*(1-a);bowler.limbs[1].rotation.x=.1;}g.updateMatrixWorld(true);}
  function release(){animateBowler(intent.runupSeconds);const hand=new THREE.Vector3();bowler.hand.getWorldPosition(hand);sim=new BallSimulation(makeRelease(intent,v(hand.x,hand.y,hand.z)),{seed:intent.seed,pitch:PROFILES[$('surface').value]});sim.event('BowlerAction',{armSlot:intent.armSlot,wrist:intent.wrist,runupSeconds:intent.runupSeconds});state='flight';phaseTime=0;lastInput='';}
  function showAnalysis(){ledger.commit(deliveryId,sim.events);score();state='result';control.active=false;const pitched=sim.events.find(e=>e.type==='BallPitched'),contact=sim.contact;const result=sim.result==='MISSED'?(sim.events.some(e=>e.type==='WideDetected')?'WIDE':'MISSED'):sim.result;
    $('resultTitle').textContent=result==='IN PLAY'?'BAT CONTACT':result;$('resultDetail').textContent=contact?(contact.edge?'Off the edge.':'Off the face.')+' Review the path below.':result==='BOWLED'?'The ball crossed the wicket.':'No bat contact. Reset and read the next action.';
    $('releaseSpeed').textContent=(length(sim.release.velocity)*3.6).toFixed(1)+' km/h';$('bounceDistance').textContent=pitched?(RULES.stumpZ-pitched.position.z).toFixed(2)+' m':'Full toss';$('batSpeed').textContent=contact?(contact.batSpeedMps*3.6).toFixed(1)+' km/h':'—';$('contactPoint').textContent=contact?`${Math.round(contact.batLocalM.x*1000)} / ${Math.round(contact.batLocalM.y*1000)} mm`:'No contact';$('analysis').classList.remove('hidden');$('activity').textContent='DELIVERY COMPLETE';$('scrub').max=sim.time.toFixed(3);$('scrub').value='0';$('feedback').innerHTML='';
  }
  function renderBat(p){const axes=batBasis(p.yaw,p.loft),matrix=new THREE.Matrix4().makeBasis(new THREE.Vector3(axes.right.x,axes.right.y,axes.right.z),new THREE.Vector3(axes.up.x,axes.up.y,axes.up.z),new THREE.Vector3(-axes.normal.x,-axes.normal.y,-axes.normal.z));batRig.quaternion.setFromRotationMatrix(matrix);batRig.position.set(p.position.x+(p.leave?(control.hand==='left'?-.75:.75):0),p.position.y,p.position.z);}
  function togglePause(){if(state==='ready'||activeModal)return;paused=!paused;control.keys.clear();control.lastPointer=null;$('pause').textContent=paused?'▶':'Ⅱ';$('activity').textContent=paused?'PAUSED':'READY';}
  function openDialog(id){wasPaused=paused;paused=true;control.keys.clear();activeModal=id;$(id).showModal();}
  for(const id of ['instructions','settings'])$(id).addEventListener('close',()=>{activeModal=null;paused=wasPaused;control.lastPointer=null;accumulator=0;if(resetAfterClose){resetAfterClose=false;startDelivery();}});
  $('help').onclick=()=>openDialog('instructions');$('settingsButton').onclick=()=>openDialog('settings');$('closeHelp').onclick=()=>$('instructions').close();$('gotit').onclick=()=>$('instructions').close();$('closeSettings').onclick=()=>$('settings').close();$('applySettings').onclick=()=>{configure();$('settings').close();};
  $('play').onclick=startDelivery;$('next').onclick=startDelivery;$('pause').onclick=togglePause;$('sound').onclick=()=>{soundOn=!soundOn;$('sound').textContent=soundOn?'SOUND ON':'SOUND OFF';audioHit(400,.1);};
  $('reset').onclick=()=>{ledger=new Ledger();deliveryId=0;score();resetAfterClose=true;$('settings').close();};
  control.attach(canvas,{isBlocked:()=>paused||!!activeModal||state==='replay'||state==='result',onPause:togglePause,onLeave:()=>{$('activity').textContent='LEAVE';}});
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused){paused=true;control.keys.clear();control.lastPointer=null;$('pause').textContent='▶';$('activity').textContent='PAUSED';}});
  $('replay').onclick=()=>{if(!sim)return;state='replay';paused=false;replayTime=0;$('replayBar').classList.remove('hidden');$('activity').textContent='POST-BALL REPLAY';removeTrail();const points=sim.frames.map(f=>new THREE.Vector3(f.position.x,f.position.y,f.position.z));trajectory=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:0xd8f58e,transparent:true,opacity:.7}));scene.add(trajectory);};
  $('scrub').addEventListener('input',()=>{if(!sim)return;state='replay';paused=true;replayTime=Number($('scrub').value);});$('replaySpeed').onchange=()=>replaySpeed=Number($('replaySpeed').value);$('replayPlay').onclick=()=>{if(replayTime>=sim.time)replayTime=0;paused=!paused;};
  $('download').onclick=()=>{if(!sim)return;const blob=new Blob([JSON.stringify(sim.export())],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`crease-delivery-${deliveryId}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
  function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<innerHeight?75:64;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();score();
  camera.position.set(.10,1.72,1.8);camera.lookAt(0,1.45,-19);scene.add(batRig);renderBat(pose);
  function frame(now){requestAnimationFrame(frame);const elapsed=Math.min((now-last)/1000,.25);last=now;if(!paused&&state!=='replay')accumulator+=elapsed;
    while(accumulator+1e-12>=STEP&&!paused&&state!=='replay'){accumulator-=STEP;phaseTime+=STEP;pose=control.step(STEP);if(state==='runup'&&phaseTime>=intent.runupSeconds)release();if(state==='flight'){const serialized=JSON.stringify(pose);if(serialized!==lastInput){sim.inputs.push({tick:sim.tick+1,bat:JSON.parse(serialized)});lastInput=serialized;}sim.step(pose);for(;lastEvent<sim.events.length;lastEvent++){const e=sim.events[lastEvent];if(e.type==='BatContact'){audioHit(e.edge?350:650,.09,.18);navigator.vibrate?.(18);$('activity').textContent=e.edge?'EDGE':'CONTACT';}else if(e.type==='BallPitched')audioHit(100,.05,.025);}if(sim.dead)showAnalysis();}}
    if(state==='runup'){animateBowler(phaseTime);bowler.hand.getWorldPosition(ball.position);}else if(state==='flight'||state==='result'){ball.position.set(sim.position.x,sim.position.y,sim.position.z);bowler.limbs[3].rotation.x=-Math.PI+Math.min(sim.time,.5)*6;}
    if(state==='replay'&&sim){if(!paused)replayTime=Math.min(sim.time,replayTime+elapsed*replaySpeed);const a=sim.frames[Math.min(sim.frames.length-1,Math.floor(replayTime/.01))];ball.position.set(a.position.x,a.position.y,a.position.z);if(a.bat)pose=a.bat;$('scrub').value=String(replayTime);$('replayTime').textContent=replayTime.toFixed(2)+' s';if(replayTime===sim.time)paused=true;}
    if(sim){const seam=state==='replay'?sim.frames[Math.min(sim.frames.length-1,Math.floor(replayTime/.01))].seamNormal:sim.seamNormal;const n=new THREE.Vector3(seam.x,seam.y,seam.z);ball.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),n);}
    camera.position.x=(control.hand==='left'?-.10:.10)+control.foot.x;camera.position.z=1.8+control.foot.z*.4;renderBat(pose);renderer.render(scene,camera);
  }requestAnimationFrame(frame);
  try{document.modelContext?.registerTool({name:'get_cricket_score',description:'Read nets statistics and play state; no future delivery information.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({contacts:ledger.contacts,deliveries:ledger.deliveries,legalBalls:ledger.legalBalls,wickets:ledger.wickets,boundaryRuns:ledger.boundaryRuns,state,paused,inputMode:control.mode})});}catch{}
}
